        public void Print(
            IFloraGetter item,
            StructuredStringBuilder sb,
            string? name = null,
            Flora.Mask<bool>? printMask = null)
        {
            if (name == null)
            {
                sb.AppendLine($"Flora =>");
            }
            else
            {
                sb.AppendLine($"{name} (Flora) =>");
            }
            using (sb.Brace())
            {
                ToStringFields(
                    item: item,
                    sb: sb,
                    printMask: printMask);
            }
        }
        
