        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IFloraGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.PreviewTransform, out var PreviewTransformInfo))
            {
                yield return PreviewTransformInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SnapTemplate, out var SnapTemplateInfo))
            {
                yield return SnapTemplateInfo;
            }
            if (FormLinkInformation.TryFactory(obj.DefaultLayer, out var DefaultLayerInfo))
            {
                yield return DefaultLayerInfo;
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Destructible is {} DestructibleItems)
            {
                foreach (var item in DestructibleItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Keywords is {} KeywordsItem)
            {
                foreach (var item in KeywordsItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (obj.Properties is {} PropertiesItem)
            {
                foreach (var item in PropertiesItem.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.Quest, out var QuestInfo))
            {
                yield return QuestInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Ingredient, out var IngredientInfo))
            {
                yield return IngredientInfo;
            }
            if (FormLinkInformation.TryFactory(obj.SNAM, out var SNAMInfo))
            {
                yield return SNAMInfo;
            }
            if (FormLinkInformation.TryFactory(obj.FarmAmountGlobal, out var FarmAmountGlobalInfo))
            {
                yield return FarmAmountGlobalInfo;
            }
            if (FormLinkInformation.TryFactory(obj.FarmIntervalGlobal, out var FarmIntervalGlobalInfo))
            {
                yield return FarmIntervalGlobalInfo;
            }
            yield break;
        }
        
