                                skipHeader: false));
                        return new ParseResult((int)Flora_FieldIndex.ObjectPlacementDefaults, type);
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)Flora_FieldIndex.VMAD)
                    {
                        _OPDSLocation = (stream.Position - offset);
                        return new ParseResult((int)Flora_FieldIndex.OPDS, type);
                    }
                    else
